import{_ as a,o as n,a as p,b as e}from"./app.C41L12d5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"reg矢量计算","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_vector_compute"},{"text":"寄存器数据搬入","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_data_load/reg_data_load"},{"text":"load_broadcast","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_data_load/load_broadcast"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/reg_vector_compute/reg_data_load/load_broadcast.md","filePath":"api/SIMD-API/tensor_api/reg_vector_compute/reg_data_load/load_broadcast.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788242648000}'),c={name:"api/SIMD-API/tensor_api/reg_vector_compute/reg_data_load/load_broadcast.md"};function t(l,s,o,d,r,i){return n(),p("div",null,[...s[0]||(s[0]=[e(`<div><article class="markdown-body"><h1>load_broadcast</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;tensor_api/experimental/arch/vector/reg_data_load.h&quot;</code>，命名空间为<code>asc::te::experimental</code>。</p><p><code>load_broadcast</code>用于从Unified Buffer（UB）Tensor中搬入数据，并按照<code>broadcast_mode</code>指定的方式广播到一个<a href="../reg_tensor/reg_tensor.html">reg_tensor</a>。</p><p>传入<code>coord</code>时，从<code>tensor.engine() + tensor.layout()(coord)</code>对应的元素开始搬入；不传入<code>coord</code>时，从<code>tensor</code>起始位置开始搬入。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><ul><li><p>指定坐标：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">broadcast_mode</span><span class="w"> </span><span class="n">brc_mode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">broadcast_mode</span><span class="o">::</span><span class="n">elem</span><span class="p">,</span>
<span class="w">          </span><span class="k">typename</span><span class="w"> </span><span class="nc">Tensor</span><span class="p">,</span>
<span class="w">          </span><span class="k">typename</span><span class="w"> </span><span class="nc">Coord</span><span class="o">&gt;</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">decltype</span><span class="p">(</span><span class="k">auto</span><span class="p">)</span><span class="w"> </span><span class="n">load_broadcast</span><span class="p">(</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">Tensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">tensor</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">Coord</span><span class="o">&amp;</span><span class="w"> </span><span class="n">coord</span><span class="p">)</span>
</code></pre></div></li><li><p>从Tensor起始位置搬入：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">broadcast_mode</span><span class="w"> </span><span class="n">brc_mode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">broadcast_mode</span><span class="o">::</span><span class="n">elem</span><span class="p">,</span>
<span class="w">          </span><span class="k">typename</span><span class="w"> </span><span class="nc">Tensor</span><span class="o">&gt;</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">decltype</span><span class="p">(</span><span class="k">auto</span><span class="p">)</span><span class="w"> </span><span class="n">load_broadcast</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">Tensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">tensor</span><span class="p">)</span>
</code></pre></div></li></ul><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td><code>brc_mode</code></td><td>广播模式，类型为<code>broadcast_mode</code>，默认值为<code>broadcast_mode::elem</code>。具体取值请参考<a href="#%E8%A1%A83-broadcast_mode%E5%8F%82%E6%95%B0%E8%AF%B4%E6%98%8E">表3</a>。</td></tr><tr><td><code>Tensor</code></td><td>源Tensor类型，由函数实参自动推导。Tensor必须位于UB。</td></tr><tr><td><code>Coord</code></td><td>源Tensor的坐标类型，由函数实参自动推导。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td><code>tensor</code></td><td>输入</td><td>源Tensor，必须位于UB。</td></tr><tr><td><code>coord</code></td><td>输入</td><td>搬入起始元素在<code>tensor</code>逻辑布局中的坐标。</td></tr></tbody></table><p><a id="表3-broadcast_mode参数说明"></a></p><p><strong>表3</strong> <code>broadcast_mode</code>参数说明</p><table><thead><tr><th>取值</th><th>含义</th><th>搬入起始地址对齐约束（Byte）</th></tr></thead><tbody><tr><td><code>broadcast_mode::elem</code></td><td>从UB读取一个元素，并将该元素广播到目的寄存器的所有元素位置。</td><td><code>sizeof(Tensor::data_type)</code></td></tr><tr><td><code>broadcast_mode::datablock</code></td><td>从UB读取一个DataBlock（32B），并将该DataBlock重复广播到整个目的寄存器。</td><td>32</td></tr><tr><td><code>broadcast_mode::elem2datablock</code></td><td>依次读取VL/32B个元素，并将每个元素分别广播到目的寄存器的一个DataBlock内。</td><td>16bit类型为VL/16；32bit类型为VL/8</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><table><thead><tr><th><code>brc_mode</code></th><th>支持的数据类型</th></tr></thead><tbody><tr><td><code>elem</code>、<code>datablock</code></td><td><code>int8_t</code>、<code>uint8_t</code>、<code>int16_t</code>、<code>uint16_t</code>、<code>int32_t</code>、<code>uint32_t</code>、<code>half</code>、<code>bfloat16_t</code>、<code>float</code>、<code>hifloat8_t</code>、<code>fp8_e4m3fn_t</code>、<code>fp8_e5m2_t</code>、<code>fp8_e8m0_t</code>、<code>int4x2_t</code>、<code>fp4x2_e2m1_t</code>、<code>fp4x2_e1m2_t</code></td></tr><tr><td><code>elem2datablock</code></td><td><code>int16_t</code>、<code>uint16_t</code>、<code>int32_t</code>、<code>uint32_t</code>、<code>half</code>、<code>bfloat16_t</code>、<code>float</code></td></tr></tbody></table><p>未列出的类型或模式组合会产生编译期错误。</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>返回<code>reg_tensor&lt;typename Tensor::data_type&gt;</code>，其<code>reg</code>成员保存广播结果。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>仅支持位于UB的Tensor。</li><li>搬入起始地址必须满足<a href="#%E8%A1%A83-broadcast_mode%E5%8F%82%E6%95%B0%E8%AF%B4%E6%98%8E">表3</a>中的对齐约束。</li><li>传入<code>coord</code>时，坐标维数必须与Tensor布局匹配，且坐标不能越界。</li><li>接口只初始化返回对象的<code>reg</code>成员，不初始化<code>mask</code>成员。将结果用于读取<code>mask</code>的寄存器计算或<code>store</code>模式前，必须调用<code>with_mask</code>绑定有效mask。</li><li>寄存器数据搬入应在<code>__simd_vf__</code>函数或<code>__simd_callee__</code>函数中完成。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>以下示例从UB读取一个<code>float</code>元素，并将其广播到整个寄存器。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/experimental/arch/vector/mask_reg_compute.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/experimental/arch/vector/reg_data_load.h&quot;</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">SrcTensor</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">LoadScalarBroadcast</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">SrcTensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load_broadcast</span><span class="o">&lt;</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">broadcast_mode</span><span class="o">::</span><span class="n">elem</span><span class="o">&gt;</span><span class="p">(</span>
<span class="w">        </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="mi">0</span><span class="p">));</span>
<span class="w">    </span><span class="n">value</span><span class="p">.</span><span class="n">with_mask</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">all_mask</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="p">());</span>
<span class="w">    </span><span class="c1">// 使用value完成后续寄存器计算。</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const m=a(c,[["render",t]]);export{h as __pageData,m as default};
